function simBmBind(){var a=$('#sim-bml');if(a)a.onclick=function(e){e.preventDefault();toast('ลากปุ่มนี้ไปวางที่แถบบุ๊กมาร์ก แล้วกดในหน้า CMP',1)};var c=$('#sim-bmc');if(c)c.onclick=function(){var t='javascript:'+encodeURIComponent(A.simBm||'');(navigator.clipboard?navigator.clipboard.writeText(t):Promise.reject()).then(function(){toast('คัดลอกแล้ว · สร้างบุ๊กมาร์กใหม่แล้ววางในช่อง URL')}).catch(function(){prompt('คัดลอกโค้ดนี้ไปใส่ช่อง URL ของบุ๊กมาร์ก',t)})}}
/* CSV (ชีต Dtac ดาวน์โหลดเป็น CSV · หัวคอลัมน์แถวแรก) → ส่งทีละ 400 แถว */
function simCsv(t){var rows=[],row=[],f='',q=false;t=String(t||'').replace(/^﻿/,'');for(var i=0;i<t.length;i++){var c=t[i];if(q){if(c==='"'){if(t[i+1]==='"'){f+='"';i++}else q=false}else f+=c}else if(c==='"')q=true;else if(c===','){row.push(f);f=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&t[i+1]==='\n')i++;row.push(f);rows.push(row);row=[];f=''}else f+=c}if(f||row.length){row.push(f);rows.push(row)}
  var h=(rows.shift()||[]).map(function(x){return x.trim()});return rows.filter(function(r){return r.some(function(x){return x!==''})}).map(function(r){var o={};h.forEach(function(k,i){o[k]=String(r[i]==null?'':r[i]).replace(/^'/,'').replace(/^="(.*)"$/,'$1').trim()});return o})}
function simImp(file,kind){if(!file)return;var out=$('#sim-ir');var rd=new FileReader();rd.onload=function(){var L=simCsv(rd.result);if(!L.length){out.textContent='ไม่พบข้อมูลในไฟล์';return}
  if(kind==='master'&&!('msisdn' in L[0])){out.textContent='ไฟล์นี้ไม่มีคอลัมน์ msisdn (ต้องเป็นแท็บ SIM_Master)';return}if(kind==='monthly'&&!('month' in L[0]&&'daysActive' in L[0])){out.textContent='ไฟล์นี้ไม่ใช่แท็บ SIM_Monthly';return}
  ask({title:'นำเข้า '+L.length.toLocaleString('th-TH')+' แถว?',desc:kind==='master'?'เบอร์ใหม่จะถูกเพิ่ม · เบอร์ที่มีแล้วไม่ถูกทับ · ไซต์/ค่าบริการเติมเฉพาะช่องว่าง':'สรุปรายเดือน (ทับตามเดือน+เบอร์)',buttons:[{k:'no',label:'ยกเลิก'},{k:'ok',label:'นำเข้า',cls:'pri'}]}).then(function(k){if(k!=='ok')return;var n=0,sk=0,i=0;
    var step=function(){if(i>=L.length){out.innerHTML='นำเข้าแล้ว '+n.toLocaleString('th-TH')+' แถว · ข้าม '+sk.toLocaleString('th-TH');toast('นำเข้าเสร็จ');return}var part=L.slice(i,i+400);i+=400;out.textContent='กำลังนำเข้า '+Math.min(i,L.length)+' / '+L.length+' …';
      aCall('simImport',{kind:kind,rows:part,last:i>=L.length?1:0}).then(function(r){n+=r.n;sk+=r.skip;step()}).catch(function(e){out.innerHTML='<span style="color:#C0392B">'+esc(e.message)+'</span>'})};step()})};rd.readAsText(file)}
/* ใบแจ้งหนี้ dtac (.xlsx) → แท็บ Detail · หาแถวหัวตารางที่มี Subscriber No. · ข้ามแถวสรุปบัญชี (Subscriber = !) · ส่งทีละ 400 เบอร์ */
function simBillParse(wb){var ws=wb.Sheets['Detail']||wb.Sheets[wb.SheetNames[0]];if(!ws)throw new Error('ไม่พบแท็บ Detail ในไฟล์');var A2=XLSX.utils.sheet_to_json(ws,{header:1,defval:'',raw:true});
  var hi=-1;for(var i=0;i<Math.min(A2.length,30);i++){if(A2[i].some(function(c){return /^subscriber no\.?$/i.test(String(c).replace(/\s+/g,' ').trim())})){hi=i;break}}if(hi<0)throw new Error('ไม่พบคอลัมน์ Subscriber No. (ต้องเป็นไฟล์ใบแจ้งหนี้ของ dtac)');
  var H=A2[hi].map(function(c){return String(c).replace(/\s+/g,' ').trim().toLowerCase()}),col=function(re){for(var j=0;j<H.length;j++)if(re.test(H[j]))return j;return -1};
  var cS=col(/^subscriber no/),cP=col(/^package name/),cI=col(/^invoice period$/),cF=col(/^fixpayment.*main/),cD=col(/^other discount/),cT=col(/^total charge/);
  if(cT<0||cI<0)throw new Error('ไม่พบคอลัมน์ Total Charge หรือ Invoice Period');
  var rows=[],per='';A2.slice(hi+1).forEach(function(r){var ms=String(r[cS]||'').replace(/\D/g,'');if(!/^66\d{8,11}$/.test(ms))return;var ip=String(r[cI]||'').replace(/\D/g,'');if(/^\d{6}$/.test(ip))per=per||ip;rows.push({msisdn:ms,pkg:cP>=0?String(r[cP]||''):'',fee:cF>=0?+r[cF]||0:0,disc:cD>=0?+r[cD]||0:0,charge:+r[cT]||0})});
  if(!per)throw new Error('ไม่พบรอบบิล (Invoice Period)');return {month:per.slice(0,4)+'-'+per.slice(4,6),rows:rows}}
function simBill(file){if(!file)return;var out=$('#sim-ir');out.textContent='กำลังอ่านไฟล์…';pyXlsx().then(function(X){return file.arrayBuffer().then(function(b){return X.read(b,{type:'array'})})}).then(function(wb){var R=simBillParse(wb),tot=R.rows.reduce(function(t,r){return t+r.charge},0);
    if(!R.rows.length){out.textContent='ไม่พบเบอร์ในไฟล์';return}
    ask({title:'นำเข้าใบแจ้งหนี้ '+simMon(R.month)+' '+(+R.month.slice(0,4)+543)+'?',desc:R.rows.length.toLocaleString('th-TH')+' เบอร์ · รวม '+simBaht(Math.round(tot*100)/100)+' ก่อน VAT ('+simBaht(Math.round(tot*107)/100)+' รวม VAT) · ถ้ามีรอบนี้อยู่แล้วจะแทนทั้งรอบ',buttons:[{k:'no',label:'ยกเลิก'},{k:'ok',label:'นำเข้า',cls:'pri'}]}).then(function(k){if(k!=='ok'){out.textContent='';return}var i=0,n=0;
      var step=function(){if(i>=R.rows.length){out.innerHTML='นำเข้าใบแจ้งหนี้ '+simMon(R.month)+' แล้ว '+n.toLocaleString('th-TH')+' เบอร์';toast('นำเข้าใบแจ้งหนี้แล้ว');return}var part=R.rows.slice(i,i+400),first=i===0;i+=400;out.textContent='กำลังนำเข้า '+Math.min(i,R.rows.length)+' / '+R.rows.length+' …';
        aCall('simImport',{kind:'bill',month:R.month,rows:part,first:first?1:0,last:i>=R.rows.length?1:0}).then(function(r){n+=r.n;step()}).catch(function(e){out.innerHTML='<span style="color:#C0392B">'+esc(e.message)+'</span>'})};step()})}).catch(function(e){out.innerHTML='<span style="color:#C0392B">'+esc(e.message)+'</span>'})}
/* ผู้เห็นเมนู SIM Monitor (ผู้ดูแลระบบ) · ช่องค้นหาชื่อพร้อมรูปแบบเดียวกับเคส Service (svaAv) */
function simAccMount(){var box=$('#sim-acc');aCall('simAccessInfo').then(function(r){var G={sel:(r.codes||[]).slice(),emps:r.emps||[],dirty:false};var draw=function(){var EC={};G.emps.forEach(function(e){EC[e.c]=e});
  box.innerHTML='<div class="sva-h"><div><b>ผู้เห็นเมนู SIM Monitor</b><small>ผู้ดูแลระบบเห็นเสมอ · คนในรายชื่อเห็นเมนู ดูข้อมูล สร้างคีย์ซิงก์ และกรอกข้อมูลไซต์ได้</small></div></div><div class="sva-chips">'+(G.sel.length?G.sel.map(function(c){var e=EC[c]||{c:c,n:'รหัส '+c,k:'',i:''};return '<span class="sva-chip">'+svaAv(e,24)+'<span>'+esc(e.k||e.n)+'</span><button type="button" data-simax="'+esc(c)+'" aria-label="เอา '+esc(e.n)+' ออก">×</button></span>'}).join(''):'<span class="faint">ยังไม่มีใคร (เห็นเฉพาะผู้ดูแลระบบ)</span>')+'</div>'+
    '<div class="sva-add"><label class="svc-q sva-q">'+svcI('search',16)+'<input class="sva-in" id="sim-ai" type="search" placeholder="พิมพ์ชื่อ ชื่อเล่น หรือรหัสพนักงาน เพื่อเพิ่ม…" autocomplete="off" aria-label="ค้นหาพนักงาน"></label><div class="sva-ls" id="sim-al" hidden></div></div><div class="sva-act"><span class="faint" style="font-size:12.5px">'+G.sel.length+' คน</span><span class="sp"></span><button class="btn sim-bp" id="sim-as"'+(G.dirty?'':' disabled')+'>บันทึกผู้เห็นเมนู</button></div>';
  loadPhotos();var q=$('#sim-ai'),ls=$('#sim-al');q.oninput=function(){var t=q.value.trim().toLowerCase();if(!t){ls.hidden=true;return}var L=G.emps.filter(function(e){return G.sel.indexOf(e.c)<0&&(e.n+' '+e.k+' '+e.c+' '+e.p).toLowerCase().indexOf(t)>=0}).slice(0,30);ls.hidden=false;
    ls.innerHTML=L.length?L.map(function(e){return '<button type="button" class="sva-o" data-simaa="'+esc(e.c)+'">'+svaAv(e,32)+'<span class="sva-on"><b>'+esc(e.n)+(e.k?' ('+esc(e.k)+')':'')+'</b><small>รหัส '+esc(e.c)+(e.p?' · '+esc(e.p):'')+'</small></span><span class="sva-plus">+ เพิ่ม</span></button>'}).join(''):'<div class="faint" style="padding:10px 12px">ไม่พบพนักงาน</div>';loadPhotos();
    ls.querySelectorAll('[data-simaa]').forEach(function(o){o.onclick=function(){G.sel.push(o.dataset.simaa);G.dirty=true;draw();var nq=$('#sim-ai');if(nq)nq.focus()}})};
  box.querySelectorAll('[data-simax]').forEach(function(x){x.onclick=function(){G.sel=G.sel.filter(function(c){return c!==x.dataset.simax});G.dirty=true;draw()}});
  $('#sim-as').onclick=function(){var bt=this;busy(bt,1);aCall('simAccessSave',G.sel).then(function(r2){G.sel=(r2.codes||[]).slice();G.dirty=false;toast('บันทึกผู้เห็นเมนู SIM Monitor แล้ว · '+G.sel.length+' คน');draw()}).catch(function(e){busy(bt,0);toast(e.message,1)})}};draw()}).catch(function(e){box.innerHTML='<div class="alert">'+esc(e.message)+'</div>'})}

/* ปุ่มบุ๊กมาร์ก = simBmMain (sim-bm.js) เป็นข้อความ javascript: · คีย์ฝังในปุ่ม */
function simBmCode(api,key,hr){return ('('+String(simBmMain)+')('+JSON.stringify(String(api))+','+JSON.stringify(String(key).replace(/[^\w]/g,''))+','+JSON.stringify(String(hr))+',"")').replace(/\n\s*/g,'')}
